const t=JSON.parse(`{"index":{"giveawayPresentation":{"text":"Проведение онлайн-конкурса — один из самых привлекательных и эффективных способов продвижения вашего бренда или бизнеса.","actionButton":"Откройте для себя сейчас"},"sections":{"giveawayPickers":{"title":"Выборки для розыгрышей и бесплатные инструменты для розыгрышей"},"chatUseCases":{"title":"Автоматизируйте взаимодействие с Instagram"},"socialMediaViewers":{"title":"Лучшие бесплатные инструменты для Instagram"}}},"account":{"credits":{"subscription":{"title":"У вас есть активная подписка","description":"Во время подписки вы можете делать неограниченные раздачи до {entryText} записей и пользоваться особыми привилегиями подписки.","link":"Сведения о подписке"}}},"giveaway":{"slug":{"notFound":"Конкурс не найден"},"result":{"slug":{"winners":{"title":"Победители","text":"Через {simpliers} {giveaway}"},"substitutes":{"title":"Запасные победители","text":"Через {simpliers} {giveaway}"},"resulting":{"countdown":{"label":"Таймер обратного отсчета","creditSuggestion":{"title":"Вы можете купить кредит, чтобы установить таймер обратного отсчета.","button":"Активировать сейчас"}},"seconds":"Секунды","startContestButton":"Начать конкурс"},"seeEntries":{"button":"Посмотреть записи"}}},"index":{"freeGiveawayTool":{"title":"Бесплатные средства выбора имени","list":{"title":"Онлайн случайный выбор"}},"pickers":{"title":"Сборщики конкурса","text":"Соберите все работы из ваших СМИ и честно и прозрачно выберите победителей.","instagram":{"title":"Выбор конкурса {br} в Instagram"},"twitter":{"title":"Выбор конкурса {br} в Твиттере"},"tiktok":{"title":"Выбор конкурса TikTok {br}","text":"Выберите победителей из целых комментариев."},"youtube":{"title":"Выбор конкурса YouTube {br}"},"facebook":{"title":"Facebook {br} Выборщик Розыгрыша"},"multi":{"title":"Выбор конкурса для нескольких постов {br}"}},"create":{"title":"Создать конкурс сейчас","text":"{simpliers} поможет вам создать конкурс"},"games":{"title":"Игры","rollDice":{"title":"Игральная кость"},"shortStraw":{"title":"короткая соломинка"},"flipCoin":{"title":"Флип монета"}},"tools":{"title":"Инструменты","profilePictureDownloader":{"title":"Загрузчик изображений профиля","text":"Загрузите фотографии профиля любого пользователя Instagram в высоком разрешении."},"storyViewer":{"title":"Инстаграм-просмотрщик историй","text":"Просматривайте истории Instagram без входа в систему и анонимно.","withoutSeen":"Без входа и анонимно"}}},"games":{"roll-dice":{"title":"Игра в кости онлайн","text":"Бросьте кости и откройте для себя веселую игру.","diceNumber":"Количество кубиков","button":"Игральная кость","resetButton":"Перезагрузить","texts":[{"title":"Как работает онлайн-инструмент Roll Dice?","text":"Программа броска костей — это онлайн-игра, в которой вы можете бросать кости, не вставая со своего места. Приложение для броска виртуальных костей позволяет генерировать случайные числа от 1 до 6 для каждой кости."},{"title":"Как вы бросаете кости онлайн с друзьями?","text":"Если вы хотите сыграть в игру с костями или выбрать что-то случайное, бросьте кости и оставьте решение на волю случая. Когда вы бросаете кости, результат появится сразу. {br} Играйте в бесплатную игру Simpliers Dice Roll для всех игр с костями, где требуется удача, риск и быстрые решения. {br} Игра в кости — это веселый и простой способ получить случайное число. Вы можете использовать его в азартных играх, таких как нарды и монополия, или оставить решение вашего следующего хода на волю случая. {br} Вы можете использовать игру в кости, чтобы случайным образом выбрать любое занятие или просто для развлечения."},{"title":"Как играть в игру в кости?","text":"Выберите количество костей и нажмите кнопку «Бросить кости», чтобы увидеть результат игры в кости и сумму костей. {br} Благодаря симуляции бросания костей вы можете быстро бросать столько игральных костей, сколько захотите. {br} Вы можете создать веселое соревнование с друзьями, назвав каждую игральную кость. Когда вы бросаете кости, все автоматически суммируют очки. Просто увеличьте количество кубиков, дайте каждому кубику имя и нажмите кнопку «Бросить кубик». Вы можете закончить игру, бросив столько кубиков, сколько хотите, с помощью кнопки «Сброс»."}]},"flip-coin":{"title":"Онлайн флип монета","text":"Подбросьте монетку и откройте для себя веселую игру.","texts":[{"title":"Что такое игра Flip Coin?","text":"Вы можете оставить это на волю случая, чтобы принять важное решение или просто принять решение по мелочам в ходе обычной повседневной жизни.{br}Flip Coin — это традиционный и практичный способ разрешить спор, принять быстрое решение или честный выбор между двумя вариантами. Если вы хотите сразу же подбросить монетку, но у вас нет монеты в кармане, вам подойдет инструмент Simpliers Flip Coin."},{"title":"Как работает игра Flip Coin?","text":"Игра Simpliers Coin Flip — это инструмент, который позволяет вам подбрасывать настоящую монету в воздухе, как если бы вы ее подбрасывали.{br}Все, что вам нужно сделать, это выбрать, какой вариант будет определен как «решка», а какой будет определяются как «головы». Как только вы решили это, нажмите кнопку, и пусть решает удача.{br}В этой игре Flip a Coin (подбрасывание монеты) есть два варианта: \\"решка\\" и \\"орел\\". Нажмите кнопку «Перевернуть», чтобы увидеть, какая сторона приближается, и подбросить монету. Результат случайный. Оба варианта имеют 50% шанс на победу."},{"title":"В каких случаях я могу использовать инструмент Flip Coin?","text":"Чаще всего подбрасывание монеты используется в ситуациях, связанных с выбором между двумя исходами, такими как решение хода, решение о том, кто начинает игру или кто платит за обед. Это может помочь вам решить, покупать ли продукт, который вам нравится, или решить, кто будет делать работу по дому.{br}Инструмент Simpliers Flip Coin — это вневременной способ принять беспристрастное решение. Честное и бесплатное приложение для вас. Просто нажмите кнопку \\"Подбросить\\" и наблюдайте за вращением монеты.{br}Если вам нравится этот инструмент для подбрасывания монеты, вы можете поделиться им со своими друзьями, а при желании вы можете проверить Simpliers' Dice Roll или Short Trash Draw и позволить удачи в выборе!"}]},"list":{"variants":{"fathersDay":{"title":"Выбор подарков на День отца","text":"Запускаете кампанию к Дню отца? Загрузите список участников, добавьте подарки, такие как наборы для ухода или технические гаджеты, и случайным образом выберите победителей. Честно, быстро и бесплатно.","qas":[{"question":"Как мне провести розыгрыш ко Дню отца с помощью этого инструмента?","answer":"Загрузите участников вашей кампании в виде файла XLS или вставьте их вручную. Добавьте свои подарки ко Дню отца (например, смарт-часы, набор одеколонов, подарочную карту), установите количество победителей на подарок и нажмите \\"Начать\\". Инструмент случайным образом выбирает победителей для каждого приза."},{"question":"Какие подарки лучше всего подходят для розыгрыша на День отца?","answer":"Популярные варианты включают в себя технические аксессуары, наборы для ухода, подарочные сертификаты, наборы для барбекю и подарочные карты. Вы можете добавить несколько подарков с разным количеством победителей — например, 1 победитель для дрона и 5 победителей для подарочных карт."},{"question":"Могу ли я поделиться результатами с моими подписчиками?","answer":"Да. Инструмент генерирует сертификат результата, который можно поделиться, показывающий победителей, подарки и время розыгрыша — идеально подходит для публикации в Instagram Stories или на вашем сайте, чтобы доказать честность."}],"items":["Кожаный кошелек","Умные часы","Беспроводные наушники","Набор для бритья","Фартук для гриля","Набор инструментов","Парфюм","Поло рубашка","Кофеварка","Удочка","Гриль для барбекю","Кроссовки","Bluetooth-колонка","Кожаный ремень","Держатель для карт"]},"mothersDay":{"title":"Выбор подарков на День матери","text":"Запустите кампанию розыгрыша ко Дню матери. Загрузите свои заявки, добавьте подарки, такие как ваучеры на спа или коробки с цветами, и мгновенно выберите случайных победителей.","qas":[{"question":"Как мне организовать розыгрыш ко Дню матери?","answer":"Загрузите список участников (из комментариев в Instagram, подписок по электронной почте или вашей CRM) в формате XLS. Добавьте подарки ко Дню матери — спа-пакеты, ювелирные изделия, подписки на цветы — установите количество победителей и проведите розыгрыш."},{"question":"Могу ли я добавить несколько призов с разным количеством победителей?","answer":"Абсолютно. Добавьте ваучер на спа с 1 победителем, коробку с цветами с 3 победителями и код на скидку с 10 победителями — все в одном розыгрыше. Инструмент выбирает отдельных победителей для каждого подарка."},{"question":"Как мне собрать участников для кампании?","answer":"Большинство брендов собирают заявки через комментарии в Instagram, Google Форму или подписки по электронной почте. Экспортируйте этот список в XLS и загрузите его напрямую в инструмент."}],"items":["Букет роз","Спа ваучер","Шелковый шарф","Парфюм","Ювелирная шкатулка","Сумка","Набор для ухода за кожей","Серебряное ожерелье","Шоколадная коробка","Кулинарная книга","Персонализированная кружка","Кашемировый свитер","Чайный набор","Набор свечей","Фоторамка"]},"employeeRaffle":{"title":"Выборщик лотереи сотрудников для корпоративных мероприятий","text":"Организуйте честные розыгрыши для сотрудников на корпоративных мероприятиях. Загрузите список сотрудников, добавьте призы, такие как дополнительные дни отдыха или подарочные карты, и случайным образом выберите победителей.","qas":[{"question":"Как мне провести розыгрыш среди сотрудников на работе?","answer":"Экспортируйте список сотрудников из вашей HR-системы в формате XLS и загрузите его. Добавьте призы — дополнительные дни отпуска, подарочные карты, технические гаджеты, парковочные места — установите количество победителей на приз и проведите розыгрыш. Проецируйте это на экран на мероприятии для прозрачности."},{"question":"Является ли розыгрыш честным и проверяемым?","answer":"Да. Инструмент использует случайный алгоритм, предоставляя каждому сотруднику равные шансы. Вы можете сгенерировать сертификат результата, чтобы поделиться им с HR или опубликовать в вашем внутреннем канале Slack."},{"question":"Могу ли я использовать это для корпоративных вечеринок в конце года?","answer":"Идеально для этого. Добавьте несколько призов (например, 1 iPad, 3 ваучера на ужин, 10 подарочных карт на кофе), загрузите полный список вашей команды и проведите розыгрыш в прямом эфире во время вечеринки."}],"items":[]},"christmas":{"title":"Выборщик Рождественских Подарков","text":"Запустите рождественские розыгрыши для вашего бренда или сообщества. Загрузите участников, добавьте праздничные подарки и выберите случайных победителей с помощью праздничного розыгрыша.","qas":[{"question":"Как мне организовать рождественский розыгрыш?","answer":"Загрузите список участников вашей кампании в формате XLS. Добавьте свои рождественские подарки — праздничные корзины, электронику, подарочные карты, призы в виде уродливых свитеров — установите победителей для каждого подарка и проведите праздничную лотерею."},{"question":"Могу ли я использовать это для Тайного Санты на работе?","answer":"Да! Загрузите все имена участников, добавьте один общий подарок и проведите розыгрыш. Каждый выбранный человек соответствует в порядке. Вы можете провести несколько раундов для больших групп."},{"question":"Могу ли я настроить страницу с праздничным брендингом?","answer":"Вы можете добавить логотип вашей компании или бренда, изменить цветовую схему на праздничные красные и зеленые тона, а также убрать рекламу для чистой презентации на вашем рождественском мероприятии."}],"items":["Рождественский свитер","Набор горячего шоколада","Адвент-календарь","Подарочная карта","Уютное одеяло","Ароматическая свеча","Бутылка вина","Праздничное печенье","Фотоальбом","Умный динамик","Bluetooth наушники","Набор тапочек","Чайный набор","Настольная игра","Набор украшений"]},"worldCup":{"title":"Розыгрыш призов Кубка мира","text":"Настройте офисный пул или розыгрыш среди друзей на чемпионат мира. Загрузите имена участников, добавьте назначения команд в качестве призов и проведите жеребьевку, кто получит какую страну.","qas":[{"question":"Как работает розыгрыш призов на Кубок мира?","answer":"Загрузите участников вашего пула (коллег, друзей) в виде списка. Добавьте каждую квалифицирующуюся страну в качестве отдельного 'подарка' с 1 победителем. Проведите розыгрыш — каждому человеку случайным образом назначается страна. Это полный, честный розыгрыш за считанные секунды."},{"question":"Могу ли я использовать это для офисного пула с деньгами?","answer":"Инструмент обрабатывает часть случайного распределения. Загрузите участников вашего офиса, назначьте страны в качестве призов, и розыгрыш гарантирует, что никто не сможет пожаловаться на фаворитизм. Управляйте денежным фондом отдельно."},{"question":"Это работает и для Евро, и для Кубка Америки?","answer":"Да. Просто обновите список стран/команд для любого турнира — Евро, Кубок Америки, Лига чемпионов или любого спортивного события с командными группами."}],"items":["Турция","Аргентина","Франция","Бразилия","Испания","Англия","Германия","Португалия","Нидерланды","Хорватия","Бельгия","Уругвай","Мексика","США","Канада","Марокко","Япония","Южная Корея","Сенегал","Австралия","Швейцария","Колумбия"]},"ecommerceCoupon":{"title":"Выборщик купонов электронной коммерции","text":"Выберите случайных победителей для розыгрыша купонов вашего интернет-магазина. Загрузите заявки клиентов, добавьте коды скидок или подарочные карты в качестве призов и выберите победителей.","qas":[{"question":"Как я могу выбрать победителей для розыгрыша купонов?","answer":"Экспортируйте записи вашей кампании (подписчики по электронной почте, список заказов или участники из социальных сетей) в формате XLS. Добавьте ваши купоны в качестве подарков — например, 'код на 50% скидку' с 5 победителями, 'бесплатная доставка на год' с 1 победителем — и проведите розыгрыш."},{"question":"Могу ли я использовать это с Shopify или WooCommerce?","answer":"Да. Экспортируйте список клиентов или записи конкурса с любой платформы в формате XLS/CSV, загрузите его, добавьте свои коды скидок в качестве призов и выберите победителей."},{"question":"Как мне объявить победителей своим клиентам?","answer":"Сгенерируйте сертификат результата и поделитесь им на своем веб-сайте, в электронной рассылке или в социальных сетях. Победители перечислены с отметками времени для полной прозрачности."}],"items":["10% СКИДКА","20% СКИДКА","30% СКИДКА","50% СКИДКА","Бесплатная доставка","Купи 1, получи 1","$5 СКИДКА","$10 СКИДКА","$25 СКИДКА","VIP-доступ","Бесплатная упаковка подарков","Скидка на день рождения","Код распродажи","Пакетное предложение"]},"classroomDraw":{"title":"Розыгрыш призов для учителей","text":"Проводите розыгрыши наград для студентов. Загрузите список вашего класса, добавьте призы, такие как наклейки или пропуски на домашние задания, и случайным образом выберите победителей среди студентов.","qas":[{"question":"Как мне провести розыгрыш награды в моем классе?","answer":"Введите имена ваших учеников или загрузите список класса. Добавьте награды — пропуск на домашнее задание, дополнительный перерыв, набор наклеек, день, когда можно сидеть где угодно — установите количество победителей на награду и проведите розыгрыш. Ученикам нравится анимация обратного отсчета."},{"question":"Данные студентов в безопасности?","answer":"Не требуется вход в систему, и данные не хранятся на наших серверах. Вы можете использовать только имена для дополнительной конфиденциальности. Инструмент работает в вашем браузере."},{"question":"Могу ли я использовать это для классных вечеринок в конце года?","answer":"Идеально для этого. Добавьте несколько веселых призов, загрузите весь список класса и позвольте случайному розыгрышу создать волнение на вашем празднике."}],"items":[]},"blackFriday":{"title":"Выбор победителя розыгрыша Черной пятницы","text":"Запустите кампании розыгрыша на Черную пятницу. Загрузите заявки клиентов, добавьте призы-ударники или скидочные коды и выберите случайных победителей для вашего распродажного мероприятия.","qas":[{"question":"Как мне провести розыгрыш на Черную пятницу?","answer":"Соберите заявки на вашу кампанию Черной пятницы (социальные сети, электронная почта, регистрации в магазине). Загружайте в формате XLS, добавляйте призы, такие как скидки на распродажу, бесплатные продукты или мега купоны, и выбирайте победителей."},{"question":"Могу ли я проводить несколько флеш-розыгрышей в течение дня?","answer":"Да. Запускайте неограниченное количество раундов — организуйте часовые флеш-розыгрыши с разными призами. Обновляйте список участников и добавляйте новые подарки для каждого раунда."},{"question":"Как мне максимизировать вовлеченность в розыгрыш?","answer":"Заранее объявите время розыгрыша, требуйте конкретное действие для участия (подписка + комментарий, регистрация по электронной почте) и делитесь сертификатом результата после каждого розыгрыша, чтобы укрепить доверие к следующему."}],"items":["55 дюймовый 4K телевизор","Беспроводные наушники","Игровая консоль","Смартфон","Ноутбук","Кофемашина","Робот-пылесос","Умные часы","Планшет","Аэрогриль","Bluetooth-колонка","Камера","Дрон","Механическая клавиатура","Монитор"]},"weddingRaffle":{"title":"Выборщик лотереи свадебного приема","text":"Проводите розыгрыши на вашем свадебном приеме. Загрузите список гостей, добавьте призы, такие как центральные украшения или подарочные корзины, и выбирайте случайных победителей во время вечеринки.","qas":[{"question":"Как мне провести розыгрыш на моей свадьбе?","answer":"Загрузите список гостей в формате XLS или введите имена вручную. Добавьте призы — центральные элементы стола, бутылки вина, подарочные корзины, взносы на медовый месяц — установите победителей для каждого приза и проведите розыгрыш. Отобразите это на проекторе для всей комнаты."},{"question":"Какие призы обычно дарят пары?","answer":"Популярные варианты: центральные элементы стола (1 победитель на стол), бутылки вина/шампанского, небольшие подарочные корзины, лотерейные билеты или персонализированные сувениры. Добавьте каждый из них как отдельный подарок с собственным количеством победителей."},{"question":"Могу ли я запустить это во время живой трансляции на приеме?","answer":"Абсолютно. Откройте это на ноутбуке, подключенном к проектору. Анимированный обратный отсчет создает веселый интерактивный момент между курсами или во время послепартии."}],"items":["Таблица 1 - Семья невесты","Таблица 2 - Семья жениха","Таблица 3 - Друзья колледжа","Таблица 4 - Сотрудники"]},"valentinesDay":{"title":"Выборщик подарков на День святого Валентина","text":"Запустите кампании розыгрыша на День святого Валентина. Загружайте заявки, добавляйте романтические призы, такие как ваучеры на ужин или ювелирные изделия, и выбирайте случайных победителей для вашей акции на тему любви.","qas":[{"question":"Как мне провести розыгрыш бренда на День святого Валентина?","answer":"Соберите заявки на участие в кампании (комментарии в Instagram, отправка форм). Загрузите в формате XLS, добавьте романтические призы — ужин на двоих, спа-пакет для пар, ювелирные изделия, коробка с шоколадом — определите победителей и проведите розыгрыш."},{"question":"Какие призы вызывают наибольшее вовлечение?","answer":"Призы на основе опыта (ужины, спа-дни, уикенды) показывают лучшие результаты. Добавьте главный приз с 1 победителем и меньшие призы с большим количеством победителей, чтобы максимизировать волнение и участие."},{"question":"Могу ли я настроить страницу розыгрыша на День святого Валентина?","answer":"Да. Добавьте логотип вашего бренда, переключитесь на красную/розовую цветовую схему и уберите рекламу для чистого, соответствующего бренду опыта кампании ко Дню святого Валентина."}],"items":["Букет красных роз","Шоколадная коробка","День спа для пар","Романтический ужин","Сердечное ожерелье","Набор любовных писем","Набор часов для пары","Персонализированная фотокнига","Набор ароматических свечей","Уикенд на природе","Ювелирный подарок","Набор духов","Медвежонок","Карточка музыкального плейлиста"]},"sportsTeam":{"title":"Выбор спортивной команды и турнира","text":"Случайным образом выбирайте команды, матчи или турниры. Загружайте имена игроков или команд, добавляйте слоты групп в качестве призов и проводите прозрачный спортивный розыгрыш.","qas":[{"question":"Как мне нарисовать случайные пары для турнира?","answer":"Загрузите имена команд или игроков в виде списка. Добавьте слоты групп или позиции матчей в качестве 'подарков' (например, Группа A, Группа B с X победителями в каждой). Жеребьевка случайным образом распределяет команды по группам — так же, как на официальной жеребьевке турнира."},{"question":"Могу ли я использовать это для любительской лиги?","answer":"Да. Будь то местная футбольная лига, офисный баскетбольный турнир или игровое соревнование, загрузите участников, определите структуру турнира как призы и проведите честный розыгрыш."},{"question":"Как мне настроить порядок драфта в фэнтези?","answer":"Загрузите все имена владельцев команд. Добавьте позиции драфта в качестве призов (1-й выбор, 2-й выбор и т.д.) с 1 победителем для каждой. Розыгрыш случайным образом определяет весь порядок драфта за один раз."}],"items":["Реал Мадрид","Барселона","Манчестер Юнайтед","Ливерпуль","Бавария Мюнхен","Ювентус","ПСЖ","Манчестер Сити","Челси","Арсенал","Интер Милан","АC Милан","Атлетико Мадрид","Боруссия Дортмунд","Тоттенхэм"]},"ramadanEid":{"title":"Выборщик подарков Рамадан и Ид","text":"Запустите кампании розыгрыша на Рамадан и Ид. Загружайте заявки участников, добавляйте праздничные подарки, такие как корзины или ваучеры, и выбирайте победителей для вашей сезонной акции.","qas":[{"question":"Как мне запустить розыгрыш на Рамадан?","answer":"Соберите заявки из вашей кампании в социальных сетях во время Рамадана или из магазина. Загрузите в формате XLS, добавьте праздничные призы — ифтарные наборы, подарочные сертификаты, пожертвования на имя победителя — и проведите розыгрыш."},{"question":"Могут ли благотворительные организации и мечети это использовать?","answer":"Да. Загружайте списки бенефициаров, добавляйте пакеты помощи или подарочные предметы в качестве призов и проводите прозрачный розыгрыш. Сертификат результата обеспечивает подотчетность перед донорами."},{"question":"Это также работает для акций на Эйд?","answer":"Абсолютно. Обновите свой список и призы для кампаний на праздник Ид аль-Фитр или Ид аль-Адха и проведите новые розыгрыши для каждого праздника."}],"items":["Коробка подарков с датами","Молитвенный коврик","Набор Корана","Наряд на Ид","Парфюм","Коробка сладостей","Золотая монета","Благотворительное пожертвование","Карточка с Эйд Мубараком","Чайный сервис","Семейная фоторамка","Набор детских игрушек","Набор для хны","Декоративная тарелка"]},"halloween":{"title":"Розыгрыш и призы на Хэллоуин","text":"Запустите розыгрыши на Хэллоуин и конкурсы костюмов. Загружайте заявки участников, добавляйте жуткие призы и случайным образом выбирайте победителей для вашей кампании на Хэллоуин.","qas":[{"question":"Как мне запустить кампанию розыгрыша на Хэллоуин?","answer":"Соберите заявки из вашей кампании в социальных сетях или мероприятия на Хэллоуин. Загрузите список, добавьте жуткие призы — наборы фильмов ужасов, корзины с конфетами, подарочные карты на костюмы, билеты в дом с привидениями — и выберите победителей."},{"question":"Могу ли я использовать это для конкурса костюмов на вечеринке?","answer":"Да! Загрузите имена участников, добавьте категории призов (Самый страшный, Самый смешной, Самый креативный) в качестве отдельных подарков и случайным образом выберите победителя в каждой категории в качестве бонуса наряду с выбором судей."},{"question":"Как сделать розыгрыш в хэллоуинском стиле?","answer":"Настройте с темными цветами, добавьте логотип вашего Хэллоуинского мероприятия и проецируйте анимированный обратный отсчет на экран на вашей вечеринке для эффектногоReveal."}],"items":["Костюм вампира","Костюм ведьмы","Костюм зомби","Костюм Призрака","Маска тыквы","Декорация паука","Костюм Скелета","Корзина с конфетами","Билет на дом с привидениями","Пакет фильмов ужасов","Плюшевая черная кошка","Вырезанная тыква","Машина тумана","Пакет светящихся палочек","Набор для макияжа костюма"]},"newYears":{"title":"Выборщик подарков на Новый год","text":"Запустите новогодние и годовые кампании розыгрышей. Загружайте свои заявки, добавляйте призы с обратным отсчетом и выбирайте победителей, чтобы встретить новый год вместе с вашей аудиторией.","qas":[{"question":"Как мне провести новогодний розыгрыш с обратным отсчетом?","answer":"Загрузите свои заявки на новогоднюю кампанию. Добавьте призы для каждого часа обратного отсчета или один розыгрыш в полночь — технические гаджеты, подписочные коробки, наборы для вечеринок — и проводите розыгрыши в течение вечера."},{"question":"Могу ли я проводить часовые розыгрыши в канун Нового года?","answer":"Да. Установите отдельные розыгрыши для каждого часа. Обновите приз (например, 'Приз в 11 вечера: Набор шампанского', 'Гран-при в полночь: Уикенд по путевке') и проводите новые раунды всю ночь."},{"question":"Как я могу использовать это для ежегодной благодарности клиентам?","answer":"Экспортируйте список своих лояльных клиентов из вашей CRM. Добавьте призы в качестве благодарности, проведите розыгрыш и отправьте электронные письма победителям. Отличный способ начать новый год с добрыми намерениями."}],"items":["Шампанское","Набор праздничных шляп","Конфетти-канон","Пакет фейерверков","Календарь 2026 года","Журнал разрешений","Абонемент в спортзал","Путевка","Фитнес-трекер","Кулинарный класс","Фотоальбом","Набор вина","Билеты на концерт","Спа-день","Подарочная карта"]},"meetingSpeaker":{"title":"Случайный выбор спикера встречи","text":"Выбирайте случайных спикеров для встреч и стендапов. Загрузите список вашей команды, добавьте временные слоты для выступлений в качестве элементов и случайным образом определяйте, кто будет выступать следующим — больше никаких неловких пауз.","qas":[{"question":"Как мне случайным образом выбрать, кто будет говорить следующим на встрече?","answer":"Загрузите список вашей команды или вставьте имена. Добавьте тему повестки как 'подарок' с 1 победителем. Проведите розыгрыш, чтобы узнать, кто будет представлять. Запустите снова для следующей темы. Устраняет предвзятость и неловкость 'кто хочет начать первым?'."},{"question":"Это хорошо для стендапов Scrum?","answer":"Отлично. Загружайте участников спринта и определяйте порядок выступлений на каждом стендапе. Это поддерживает свежесть и гарантирует, что каждый получит равное время для выступления со временем."},{"question":"Могу ли я исключить людей, которые уже говорили?","answer":"Да. Удалите уже выбранные имена между раундами или настройте все пункты повестки как отдельные подарки и проведите один полный розыгрыш, чтобы назначить всех спикеров сразу."}],"items":[]},"betaTester":{"title":"Выбор бета-тестера","text":"Справедливо выбирайте бета-тестеров из вашего списка ожидания. Загружайте заявки, добавляйте слоты для бета-доступа в качестве призов и случайным образом выбирайте, кто получит ранний доступ к вашему продукту.","qas":[{"question":"Как мне справедливо выбрать бета-тестеров из моего списка ожидания?","answer":"Экспортируйте свой список ожидания из Typeform, Google Sheets или вашей базы данных в формате XLS. Добавьте 'Бета-доступ' в качестве подарка с количеством открытых слотов. Розыгрыш случайным образом выбирает тестировщиков — без учета часовых поясов, без фаворитизма."},{"question":"Могу ли я провести несколько раундов, открывая больше слотов?","answer":"Да. Удалите ранее выбранных тестировщиков, обновите список, добавьте новые слоты в качестве призов и проводите новые раунды каждый раз, когда вы увеличиваете емкость бета-тестирования."},{"question":"Как мне сообщить результаты кандидатам?","answer":"Сгенерируйте сертификат результата и поделитесь им на странице сообщества вашего продукта или в Twitter. Выбранные тестировщики видят, что они выиграли; другие видят, что процесс был прозрачным."}],"items":[]}},"title":"Бесплатный онлайн-случайный выбор","text":"Выберите случайные имена, число или любые элементы из списка. Просто вставьте свой список и выберите случайные элементы.","inputPlaceHolder":"Напишите свой список по одному пункту в строке.","texts":[{"title":"Что такое онлайн случайный выбор??","text":"Это бесплатный инструмент случайного выбора, который позволяет вам перемешивать список ваших клиентов, продуктов или любого контента и выбирать случайные имена или победителей из этого списка."},{"title":"Как использовать средство выбора случайного списка?","text":"Вы можете вставить список имен ваших участников в соответствующее поле, по одному элементу в строке. Далее вы должны выбрать количество победителей и количество замещающих победителей и нажать кнопку НАЧАТЬ КОНКУРС.\\n\\nПо истечении установленного вами времени обратного отсчета случайные победители будут выбраны из вашего списка и отображены на экране.\\n\\nС помощью бесплатного онлайн-инструмента для выбора списка вы можете легко и бесплатно рисовать."}],"subscriptionTopBar":{"subscriptionExistsText":"Вы можете делать неограниченные подарки","subscribeText":"Удалить рекламу и настроить страницу","ctaText":"Начать сейчас"},"priceOfferModal":{"mainTitle":"Делайте подарки из списка.","mainDescription":"Делайте более профессиональные подарки с помощью корпоративного дизайна без рекламы и корпоративного дизайна.","additionalFeatures":{"0":{"title":"Убрать рекламу","description":"Увеличьте количество корпоративных и профессиональных подарков, удалив рекламу."},"1":{"title":"Настройте страницу в соответствии с вашим брендом","description":"Настройте страницу, используя цвета и логотип вашего бренда. Делайте подарки профессионально."},"2":{"title":"Сохранить списки","description":"Сохраните свой список участников, чтобы вы могли легко найти его, когда вам понадобится."},"3":{"title":"Сохранить и поделиться результатами","description":"Сохраните список и результаты вашего розыгрыша и поделитесь ими с участниками. Покажите, что результаты безопасны и надежны."},"4":{"title":"Выберите уникальных победителей для каждого подарка.","description":"Выберите уникальных победителей для каждого из ваших подарков в одном и том же розыгрыше."}},"cancelButtonArea":{"resetButton":{"default":"Отменить","customization":"Отменить и сбросить настройки","saveList":"Продолжить без сохранения списка","removeAds":"Продолжайте без удаления рекламы","saveResult":"Не сохраняйте результат"}}},"clipboardError":"Не удалось получить доступ к буферу обмена. Вы можете попробовать вставить это вручную."},"randomNumber":{"variants":{"range1To10":{"title":"Генератор случайных чисел от 1 до 10","text":"Сгенерируйте случайное число от 1 до 10 мгновенно. Идеально для быстрых решений, игр и выбора очередности. Бесплатно, без регистрации.","qas":[{"question":"Каковы шансы получить любое число от 1 до 10?","answer":"Каждое число имеет равный 10% шанс быть выбранным. Генератор использует псевдослучайный алгоритм, обеспечивающий отсутствие предпочтения одного числа над другим."},{"question":"Для чего я могу использовать случайное число от 1 до 10?","answer":"Общие применения включают определение очередности ходов в играх, выбор игрока для первого хода, разрешение мелких споров, выбор между 10 вариантами или распределение задач среди небольшой группы."},{"question":"Могу ли я сгенерировать несколько чисел сразу?","answer":"Да. Установите поле 'Сколько чисел' для генерации нескольких случайных чисел от 1 до 10 одним щелчком. Переключите 'Уникальные числа', чтобы избежать повторений."}]},"range1To100":{"title":"Генератор случайных чисел от 1 до 100","text":"Сгенерируйте случайное число от 1 до 100. Отлично подходит для розыгрышей, классных мероприятий, практики лотереи и вечеринок. Мгновенно и бесплатно.","qas":[{"question":"Каждое число имеет равную вероятность появления?","answer":"Да. Каждое число от 1 до 100 имеет ровно 1% вероятность быть выбранным. За тысячи выборов каждое число появляется примерно одинаковое количество раз."},{"question":"Могу ли я использовать это для розыгрыша с пронумерованными билетами?","answer":"Абсолютно. Если вы продали 100 лотерейных билетов с номерами от 1 до 100, используйте этот генератор, чтобы честно и случайно выбрать номер выигрышного билета."},{"question":"Чем это отличается от основного генератора?","answer":"Это тот же инструмент с предустановленным диапазоном от 1 до 100 для вашего удобства. Вы все еще можете настроить диапазон, количество и параметры уникальности при необходимости."}]},"range1To1000":{"title":"Генератор случайных чисел от 1 до 1000","text":"Выберите случайное число от 1 до 1000. Полезно для крупных розыгрышей, статистической выборки,抽奖 и игровых сценариев, требующих больших диапазонов.","qas":[{"question":"Когда мне понадобится случайное число до 1000?","answer":"Масштабные розыгрыши, розыгрыши по номерам билетов, игровые сценарии с широкими диапазонами, статистическая выборка и любая ситуация, где 1-100 недостаточно. Также популярно для игр \\"угадай число\\"."},{"question":"Могу ли я сгенерировать партию уникальных чисел от 1 до 1000?","answer":"Да. Установите необходимое количество и включите 'Уникальные числа'. Инструмент сгенерирует столько неповторяющихся случайных чисел в диапазоне от 1 до 1000."},{"question":"Подходит ли это для симуляции лотерейных номеров?","answer":"Вы можете использовать его для практики или имитации розыгрышей в стиле лотереи. Установите диапазон в соответствии с правилами вашей лотереи и сгенерируйте необходимое количество уникальных выборов."}]},"range1To50":{"title":"Генератор случайных чисел от 1 до 50","text":"Сгенерируйте случайное число от 1 до 50 мгновенно. Идеально подходит для занятий в классе, подготовки настольных игр, выборов на полурынке и быстрых розыгрышей.","qas":[{"question":"Какое общее применение случайных чисел от 1 до 50?","answer":"Учителя используют его, чтобы вызывать учеников в классах до 50 человек. Он также популярен для подготовки настольных игр, выбора номеров карт или любых сценариев выбора среднего диапазона."},{"question":"Могу ли я использовать это для назначения мест или шкафчиков?","answer":"Да. Если у вас есть 50 мест или шкафчиков, генерируйте случайные числа для их справедливого распределения. Используйте переключатель 'Уникальные числа', чтобы избежать дубликатов."},{"question":"Результат действительно случайный?","answer":"Генератор использует псевдослучайный алгоритм, который рассматривает каждое число от 1 до 50 с равной вероятностью. Это справедливо и беспристрастно для любого практического использования."}]},"lottery":{"title":"Генератор случайных номеров лотереи","text":"Сгенерируйте случайные номера лотереи для вашего следующего розыгрыша. Выбирайте уникальные номера в любом диапазоне — работает для Powerball, Mega Millions, EuroMillions и местных лотерей.","qas":[{"question":"Как мне сгенерировать номера лотереи?","answer":"Установите диапазон в соответствии с вашей лотереей (например, 1-49 для многих национальных лотерей, 1-69 для Powerball). Установите количество в зависимости от того, сколько чисел вам нужно (обычно 5-6). Включите 'Уникальные числа', чтобы избежать повторений — как в настоящих лотерейных розыгрышах."},{"question":"Могу ли я использовать это для Powerball или Mega Millions?","answer":"Да. Для Powerball сгенерируйте 5 уникальных чисел от 1 до 69 для основного розыгрыша. Затем отдельно сгенерируйте 1 число от 1 до 26 для Powerball. Настройте диапазоны для любого формата лотереи."},{"question":"Увеличивает ли это мои шансы на победу?","answer":"Нет — каждая комбинация имеет одинаковую вероятность. Но это устраняет личные предвзятости (например, постоянный выбор дней рождения) и позволяет вам исследовать действительно случайные комбинации, которые вы, возможно, не рассматривали."}]},"pinCode":{"title":"Генератор случайных PIN-кодов","text":"Генерируйте случайные 4-значные или 6-значные PIN-коды мгновенно. Создавайте безопасные PIN-коды для шкафчиков, устройств, временных кодов доступа и тестовых сред.","qas":[{"question":"Как мне сгенерировать случайный 4-значный PIN-код?","answer":"Диапазон установлен на 1000-9999, что дает вам случайный 4-значный номер. Для 6-значного ПИН-кода измените диапазон на 100000-999999. Каждый ПИН-код генерируется с равной вероятностью среди всех возможных кодов."},{"question":"Это достаточно безопасно для настоящих паролей?","answer":"Это отлично подходит для временных ПИН-кодов, кодов для шкафчиков, тестовых сред и одноразовых кодов доступа. Для паролей с высокой степенью безопасности рассмотрите возможность использования специализированного менеджера паролей с генерацией на основе символов."},{"question":"Могу ли я сгенерировать несколько ПИН-кодов одновременно?","answer":"Да. Установите количество на нужное вам количество ПИН-кодов и включите 'Уникальные номера', чтобы гарантировать отсутствие дублирующих кодов в вашей партии."}]}},"title":"Генератор случайных чисел","text":"Генерировать случайные числа!","texts":[{"title":"Что такое генератор случайных чисел?","text":"Генератор случайных чисел — это инструмент, который генерирует случайные числа. Это инструмент, который можно использовать во многих областях, таких как лотереи, азартные игры, статистика, математика, наука и исследования."},{"title":"Как работает генератор случайных чисел?","text":"Инструмент генератора случайных чисел генерирует случайные числа между указанными вами числами. Вы можете генерировать случайные числа от 1 до 100, от 1 до 1000 или между любыми двумя числами. Все, что вам нужно сделать, это ввести минимальное и максимальное число, которое вы хотите сгенерировать, и нажать кнопку «Сгенерировать»."},{"title":"В каких случаях я могу использовать генератор случайных чисел?","text":"Чаще всего генератор случайных чисел используется в ситуациях, связанных с выбором между двумя исходами, например, определение хода, решение о том, кто начинает игру или кто платит за обед. Это может помочь вам решить, покупать ли продукт, который вам нравится, или решить, кто будет делать работу по дому.{br}Инструмент генератора случайных чисел simpliers — это вечный способ принять беспристрастное решение. Честное и бесплатное приложение для вас. Просто нажмите кнопку \\"Создать\\" и наблюдайте за случайным числом.{br}Если вам нравится этот генератор случайных чисел, вы можете поделиться им со своими друзьями и, если хотите, вы можете проверить simpliers' Dice Roll или Flip Coin, и пусть удача выбирает!"}]},"randomTeamGenerator":{"variants":{"soccerTeams":{"title":"Генератор футбольных команд","text":"Напишите имена всех пришедших, и составы разделятся на две случайные равные команды.","qas":[{"question":"Как разделить игроков на команды для футбольного матча?","answer":"Напишите имя каждого, кто пришёл на матч, по одному в строке, и нажмите Создать команды. Имена перемешиваются, и в обеих командах оказывается одинаковое число игроков. При нечётном числе разница составляет одного человека."},{"question":"Можно ли собрать составы по семь или восемь игроков?","answer":"Перейдите к числу человек в команде по ссылке Изменить и укажите семь или восемь. Четырнадцать игроков дают два полных состава по семь, шестнадцать игроков два состава по восемь. Оставшиеся игроки попадают в последнюю команду."},{"question":"Учитываются ли вратарь и позиции?","answer":"Деление идёт только по списку имён и без предпочтений, позиции не учитываются. Чтобы выбрать вратаря отдельно, не добавляйте его имя в список и разделите остальных игроков."}]},"pairs":{"title":"Генератор случайных пар","text":"Напишите имена, и все разделятся на случайные пары.","qas":[{"question":"Как разделить имена на пары?","answer":"Напишите имена по одному в строке и нажмите Создать команды. Список перемешивается, и в каждую пару попадает по два имени. При нечётном числе участников оставшееся имя остаётся одно в последней группе."},{"question":"Может ли одна и та же пара выпасть снова?","answer":"Список перемешивается заново при каждом запуске, поэтому пары меняются. Одна и та же пара может выпасть снова, потому что деление полностью случайное и прошлые результаты не сохраняются."},{"question":"Можно ли сделать группы по три или четыре человека?","answer":"Достаточно указать три или четыре человека в команде. По ссылке Изменить можно также перейти к делению по числу команд."}]},"classroom":{"title":"Деление на группы в классе","text":"Напишите список учеников, и группы разделятся случайно и равномерно.","qas":[{"question":"Как случайно разделить класс на группы?","answer":"Напишите имена учеников по одному в строке, выберите нужное число групп и нажмите Создать команды. Ученики распределяются равномерно, а разница между группами составляет не больше одного человека."},{"question":"Сколько групп подходит для групповой работы?","answer":"Это зависит от числа учеников. Группы по четыре человека хорошо работают в обсуждениях, а для работы в парах достаточно указать двух человек в команде. Между числом групп и размером группы можно переключаться."},{"question":"Одни и те же ученики всегда попадают в одну группу?","answer":"Список перемешивается заново при каждом запуске, поэтому деление меняется каждый раз. Кнопка Перемешать заново даёт другое распределение, а понравившийся результат копируется в буфер обмена."}]}},"texts":[{"title":"Что такое генератор случайных команд?","text":"Генератор случайных команд это бесплатный инструмент, который перемешивает введённый список имён жребием и делит его на равные команды и группы. Он подходит для футбольных матчей, групповой работы в классе, воркшопов и конкурсов в офисе. Разделить людей на команды, собрать случайные группы и провести жеребьёвку по именам решается на одном экране."},{"title":"Как работает генератор случайных команд?","text":"Напишите имена по одному в строке или вставьте их из буфера обмена. Затем укажите число команд или число человек в команде. После нажатия Создать команды список перемешивается и команды появляются на экране. {br} Если результат не подошёл, кнопка Перемешать заново даёт другое распределение. Копировать команды переносит весь список в буфер обмена, а Поделиться открывает меню обмена устройства. Повторяющиеся имена отмечаются под полем ввода."},{"title":"Составы для футбола","text":"Написать имена всех пришедших и разделить их на две команды это самый быстрый способ собрать состав. Четырнадцать игроков дают два состава по семь, шестнадцать игроков два состава по восемь; достаточно указать семь, восемь или одиннадцать человек в команде. Чтобы оставить вратаря отдельно, не добавляйте его имя в список и разделите остальных. {br} Кроме футбола так же делятся волейбол, баскетбол и группы турнира."},{"title":"Группы в классе, офисе и на мероприятиях","text":"Разделить список учеников на четыре группы, собрать тройки для командного мозгового штурма или распределить гостей по столам получается за один шаг. Деление работает в браузере, регистрация и загрузка файлов не нужны. {br} Если решение должно крутиться на колесе, у Simpliers есть бесплатное Прокрутите колесо, а для выбора одного имени Бесплатный онлайн-случайный выбор, Флип монета и Игральная кость."}],"qas":[{"question":"Как создать случайные команды?","answer":"Напишите имена по одному в строке или вставьте их из буфера обмена, выберите число команд или число человек в команде и нажмите Создать команды. Список перемешивается, и команды сразу появляются на экране."},{"question":"Как случайно разделить людей на группы?","answer":"Список перемешивается заново при каждом запуске, поэтому ни одно имя не получает преимущества из-за своего места в списке и у каждого имени равные шансы попасть в любую команду."},{"question":"Где найти онлайн-генератор команд?","answer":"Генератор случайных команд Simpliers работает в браузере, без установки приложения и без регистрации. Он одинаково работает на телефоне и компьютере, а число имён не ограничено."},{"question":"Что будет, если в командах окажется разное число человек?","answer":"При делении по числу команд имена распределяются по очереди и разница между командами составляет не больше одного человека. При делении по числу человек в команде оставшиеся имена собираются в последней команде."},{"question":"Можно ли поделиться получившимися командами?","answer":"Кнопка Поделиться открывает меню обмена устройства, а Копировать команды переносит весь список в буфер обмена. Если результат не подошёл, Перемешать заново даёт другое распределение."},{"question":"Это то же самое, что колесо для жеребьёвки команд?","answer":"Колесо выбирает одно имя за вращение, а генератор случайных команд делит весь список на команды. Для выбора одного победителя больше подходят Прокрутите колесо и Бесплатный онлайн-случайный выбор от Simpliers."}]},"shortStraw":{"title":"Игра с короткой соломинкой","text":"Откройте для себя увлекательную игру с короткой соломинкой.","texts":[{"title":"Что такое игра с короткой соломинкой?","text":"Для больших решений или небольших повседневных выборов вы можете довериться случаю. Вытягивание короткой соломинки — это традиционный и практичный способ делать случайные выборы среди группы людей, быстро принимать решения или справедливо выбирать, кого выбрать. Если вам интересно, что означает короткая соломинка, это процесс случайного выбора кого-то путем вытягивания из набора соломинок, одна из которых короче остальных. Когда вам нужно выбрать кого-то, но вы не можете найти подходящий объект для вытягивания, инструмент Simpliers Short Straw идеально подходит для вас."},{"title":"Как работает игра \\"Короткая соломинка\\"?","text":"Игра Simpliers Short Straw предлагает цифровой опыт, который имитирует реальную игру с короткой соломинкой. {br} Все, что вам нужно сделать, это выбрать спичку. Затем нажмите на спичку и позвольте случаю решить, какая из них является короткой соломинкой.{br} Чтобы узнать, кто будет выбран, случайным образом выберите соломинки и посмотрите, какая из них короткая. Этот процесс полностью случайный и осуществляется честно."},{"title":"Где можно использовать инструмент \\"Короткая соломинка\\"?","text":"Наиболее распространенные случаи использования короткой соломинки - это ситуации, когда необходимо сделать выбор между несколькими людьми, например, определить порядок в игре, решить, кто начнет, или выяснить, кто заплатит за обед. Это может помочь вам решить, кто заплатит за ужин сегодня или кто будет мыть посуду дома. {br} Инструмент Simpliers Short Straw - это вечный способ принимать беспристрастные решения. Это приложение без читов и бесплатное в использовании идеально подходит для вас. Просто вытяните соломинку и позвольте случаю решить, кто будет выбран. {br} Если вам нравится этот инструмент Short Straw, вы можете поделиться им с друзьями и ознакомиться с инструментами Simpliers Dice Roll или Coin Toss, чтобы позволить случаю принимать другие решения за вас!"}]},"spinWheel":{"variants":{"foodPicker":{"title":"Колесо выбора еды | Инструмент выбора пищи","text":"Не можете решить, что поесть сегодня? Это колесо для вас. Добавьте свои любимые блюда или рестораны и позвольте случаю решить. Практично и весело для обеда, ужина или выбора доставки.","items":["Пицца","Бургер","Суши","Такос","Паста","Салат","Курица","Сэндвич"],"qas":[{"question":"Сколько вариантов еды я могу добавить на колесо?","answer":"Добавьте столько, сколько хотите, но чтобы колесо оставалось читаемым и визуально сбалансированным, мы рекомендуем ограничиться двадцатью вариантами."},{"question":"Сохраняется ли мой список продуктов между сессиями?","answer":"Да. Все предметы, которые вы добавляете, автоматически сохраняются в вашем браузере. Закройте страницу, и ваш список будет ждать вас, когда вы вернетесь."},{"question":"Могу ли я сузить выбор и провести второй раунд?","answer":"Конечно. Выберите несколько любимых вариантов в первом раунде, затем создайте новое колесо только с этими вариантами, чтобы сделать окончательное решение."}]},"namePicker":{"title":"Случайный выбор имени | Выбор для класса и группы","text":"Добавьте список студентов или имена членов группы в колесо и выбирайте случайным образом и справедливо. Идеально подходит для классных мероприятий, выбора докладчика или распределения задач между группами.","items":["Алекс","Сэм","Джордан","Тейлор","Кейси","Морган","Райли","Эйвери"],"qas":[{"question":"Как мне загрузить весь список класса сразу?","answer":"Используйте функцию массовой вставки, чтобы добавить все имена студентов за один раз и подготовить колесо за считанные секунды. Нет необходимости вводить их по одному."},{"question":"Как мне предотвратить выбор одного и того же имени дважды за одну сессию?","answer":"После выбора имени удалите его из списка и прокрутите снова. Таким образом, каждый студент выбирается только один раз."},{"question":"Действительно ли выбор имени беспристрастен?","answer":"Да. Колесо использует алгоритм, который дает каждому имени равную вероятность. Ни один студент не имеет преимущества или недостатка."}]},"yesNo":{"title":"Да Нет Колесо | Быстрый Решатель","text":"Оставьте свою дилемму на удачу. С помощью этого колеса \\"да/нет\\" получите четкий ответ за считанные секунды, когда не можете определиться. Практичное решение для повседневных небольших колебаний.","items":["Да","Нет"],"qas":[{"question":"Могу ли я добавить варианты помимо да и нет?","answer":"Да, вы можете. Добавьте промежуточные варианты, такие как «Может быть» или «Решить позже», чтобы создать персонализированный механизм принятия решений."},{"question":"Оба результата одинаково вероятны?","answer":"Абсолютно. Колесо дает \\"да\\" и \\"нет\\" 50/50 шансы и не склоняется ни к одному из исходов."},{"question":"Должен ли я использовать это для важных решений?","answer":"Этот колесо предназначено для повседневных решений с низкими ставками. Мы не рекомендуем оставлять решения, меняющие жизнь, на произвольный инструмент."}]},"teamPicker":{"title":"Колесо выбора команды | Справедливый создатель групп","text":"Случайным образом назначьте команды для игр, турниров или групповой работы в классе. Добавьте имена участников и получите совершенно справедливое и беспристрастное разделение команд.","items":["Команда А","Команда B","Команда C","Команда D"],"qas":[{"question":"Как мне запустить выборщик для двух команд?","answer":"Добавьте все имена на колесо и вращайте по одному. Первую выборку назначьте команде один, вторую — команде два, чередуя, пока у всех не будет команда."},{"question":"Для каких событий я могу это использовать?","answer":"Игры в уличный футбол, школьные соревнования, настольные игры, проектные группы или вечеринки — любая обстановка, требующая сбалансированных команд."},{"question":"Есть ли какая-либо предвзятость в выборе?","answer":"Нет, ни один. У каждого участника есть абсолютно равные шансы быть выбранным, и результат полностью случайный."}]},"punishment":{"title":"Колесо наказаний | Весёлая вечеринка","text":"Колесо наказаний — это спасение для веселых вечеров с друзьями. Добавьте смешные задания, небольшие задачи или вопросы на правду, чтобы сделать ваши вечеринки незабываемыми. Современная альтернатива правде или действию.","items":["Спой песню","Сделайте 10 отжиманий","Смешной танец","Расскажи о своем самом неловком моменте","Молчите в течение 1 минуты","Позвонить случайному контакту","Выпейте стакан воды","Говорите с забавным акцентом"],"qas":[{"question":"Какие задания мне добавить?","answer":"Весёлые, лёгкие задания — «спой песню», «сделай 10 отжиманий», «поделись своим самым неловким моментом», «потанцуй минуту». Вещи, которые поддерживают весёлое настроение, не заходя слишком далеко."},{"question":"Могу ли я сохранить задания для следующей игры?","answer":"Да. Все ваши задания автоматически сохраняются в вашем браузере. Используйте тот же список на вашей следующей вечеринке."},{"question":"Могу ли я предотвратить появление одного и того же задания дважды?","answer":"Просто уберите задание, которое появилось, чтобы оно не повторялось в следующем раунде. Это сохраняет свежесть темпа игры."}]},"moviePicker":{"title":"Колесо выбора фильма | Что посмотреть сегодня вечером","text":"Решение о фильме с друзьями или партнером может занять часы. Добавьте фильмы, которые хотите посмотреть, в колесо, позвольте случаю решить, и сразу наслаждайтесь фильмом. То же самое работает и для телешоу.","items":["Начало","Матрица","Межзвёздный","Криминальное чтиво","Бойцовский клуб","Крёстный отец","Форрест Гамп","Темный рыцарь"],"qas":[{"question":"Мне нужно добавлять фильмы по одному?","answer":"Вы можете добавлять их по одному или использовать функцию массовой вставки, чтобы загрузить весь ваш список наблюдения в колесо за считанные секунды."},{"question":"Могу ли я создать колесо на основе категорий?","answer":"Да. Создавайте тематические колеса только с комедиями, только с ужасами или только с классикой — подберите настроение на вечер."},{"question":"Список фильмов сохранен на следующий раз?","answer":"Да. Список автоматически сохраняется в вашем браузере. Увеличивайте свой список для просмотра каждую неделю и вращайте снова, когда вам нужно сделать выбор."}]},"instagramGiveaway":{"title":"Колесо Розыгрыша в Instagram | Честный Выбор Победителя","text":"Добавьте имена пользователей участников вашего розыгрыша в Instagram на колесо и выберите победителя совершенно честным способом. Запишите свой экран, чтобы доказать прозрачность своим подписчикам.","items":["{at}пользователь1","{at}пользователь2","{at}пользователь3","{at}пользователь4","{at}пользователь5"],"qas":[{"question":"Как мне добавить все имена пользователей комментаторов?","answer":"Скопируйте имена пользователей из комментариев и вставьте их в область массовой вставки. Система размещает каждое из них как отдельный сегмент на колесе."},{"question":"Как мне доказать результат своим подписчикам?","answer":"Запишите экран вашего телефона или компьютера во время вращения. Поделившись сырой записью экрана в виде истории, вы показываете, что процесс полностью прозрачен."},{"question":"Что если мне нужно выбрать несколько победителей?","answer":"После выбора первого победителя удалите это имя и прокрутите снова. Таким образом, вы можете выбрать победителей 1-го, 2-го и резервного мест в порядке."}]},"taskAssigner":{"title":"Колесо назначения задач | Совместное использование дома и офиса","text":"Используйте это колесо для справедливого распределения домашних дел, офисных задач или проектных обязанностей. Обеспечивает беспристрастное и увлекательное разделение задач, с которым никто не сможет поспорить.","items":["Блюда","Стирка","Вакуум","Пылесосить","Продукты питания","Мусор","Кулинария","Уборка ванной"],"qas":[{"question":"Как мне разделить домашние обязанности?","answer":"Добавьте задачи, такие как мытье посуды, стирка, уборка и покупки, на колесо, а затем пусть каждый член семьи по очереди крутит его. То, что выпадет, станет его обязанностью на неделю."},{"question":"Как мне сделать так, чтобы один и тот же человек не получал всегда одну и ту же задачу?","answer":"Перераспределяйте задачи каждую неделю, чтобы обновить распределение. Это разрывает монотонность и позволяет каждому испытать разные обязанности."},{"question":"Могу ли я использовать это для порядка презентации на встрече?","answer":"Да. Добавьте имена участников команды в колесо, чтобы справедливо определить порядок презентации, повестки дня или отчетности."}]},"colorPicker":{"title":"Колесо выбора цвета | Случайный выбор цвета","text":"Выберите случайный цвет для дизайнерских работ, художественных проектов или творческих упражнений. Идеально подходит для сужения вашей палитры, когда вам нужно вдохновение.","items":["Красный","Синий","Зеленый","Желтый","Фиолетовый","Оранжевый","Розовый","Чёрный"],"qas":[{"question":"Могу ли я добавить свои собственные цвета на колесо?","answer":"Да. Добавьте названия цветов или шестнадцатеричные коды, чтобы создать колесо на основе личной палитры."},{"question":"Для каких креативных проектов это полезно?","answer":"Рисование, упражнения по графическому дизайну, выбор нарядов, вдохновение для интерьерного декора — любая творческая сфера, где вам нужен случайный толчок палитры."},{"question":"Подходит ли это для игр с детьми?","answer":"Абсолютно. Для детей, изучающих цвета, это веселый обучающий инструмент для распознавания цветов и игр на соответствие."}]},"destinationPicker":{"title":"Колесо выбора направления | Определитель путешествий и поездок","text":"Добавьте города для уикенда, страны для отпуска или заведения для вечернего выхода и освободите себя от бремени принятия решения. Это приносит как волнение от открытия, так и практическое решение.","items":["Париж","Токио","Нью-Йорк","Барселона","Рим","Стамбул","Лондон","Бали"],"qas":[{"question":"Как мне добавить туристические направления на колесо?","answer":"Добавьте города или страны, которые вы хотите посетить, по одному, или вставьте готовый список направлений, чтобы быстро создать колесо."},{"question":"Какие заведения я могу добавить для вечернего выхода?","answer":"Добавьте ближайшие кафе, рестораны, кинотеатры или бары в колесо и решите, куда пойти за секунды."},{"question":"Могу ли я отфильтровать варианты по доступному бюджету?","answer":"Добавляйте только те направления или места, которые соответствуют вашему бюджету — колесо затем выбирает из уже отфильтрованных вариантов. Вы фильтруете один раз при создании списка."}]}},"texts":[{"title":"Что такое Крутите Колесо?","text":"Крутите колесо — это веселый и практичный инструмент, используемый для случайного определения результата из набора вариантов. Независимо от того, выбираете ли вы победителя в конкурсе или принимаете веселое решение с друзьями, вращение колеса — это захватывающий и беспристрастный метод выбора. С инструментом Simpliers Крутите колесо добавьте свои варианты, прокрутите колесо и доверьтесь своей удаче."},{"title":"Как использовать \\"Крутите колесо\\"?","text":"Использовать инструмент Simpliers Spin the Wheel невероятно просто.{br}Сначала введите варианты, которые вы хотите добавить на колесо. Вы можете добавлять их по одному или в виде списка. Затем нажмите кнопку 'Крутить' и смотрите, как колесо вращается. Когда колесо остановится, вариант, на который указывает стрелка, определяется как победитель. Результаты полностью случайны и определяются справедливо."},{"title":"Где можно использовать Spin the Wheel?","text":"Инструмент \\"Крутите колесо\\" полезен в самых разных ситуациях. Вы можете использовать его для выбора победителя розыгрыша, выбора студента в классе, решения, кто будет выступать на встрече, или выбора, что поесть на ужин.{br} Инструмент \\"Крутите колесо\\" от Simpliers совершенно бесплатен и справедлив. Если вы хотите получить увлекательный опыт принятия решений, крутите колесо сейчас! Вы также можете ознакомиться с инструментами \\"Бросок кубика\\", \\"Подбрасывание монеты\\" и \\"Короткая соломинка\\" от Simpliers."}],"spinButton":"Крутить","spinning":"Крутится...","winner":"Победитель","itemsTitle":"Опции колеса","items":"элементы","add":"Добавить","bulk":"Массовое добавление списка","clearAll":"Очистить все","addAll":"Добавить все","cancel":"Отмена","history":"Предыдущие победители","clear":"Очистить","emptyState":"Добавьте как минимум 2 варианта для вращения колеса.","howItWorks":{"title":"Как работает Колесо удачи?","description":"Колесо удачи — это бесплатный онлайн-инструмент, который помогает вам принимать справедливые решения.{br}{br}Добавьте свои варианты, прокрутите колесо и наслаждайтесь увлекательным и захватывающим способом выбора."},"qas":[{"question":"Является ли Колесо удачи действительно случайным?","answer":"Да. Колесо удачи использует случайный алгоритм для определения, где остановится указатель. Каждая опция имеет равную вероятность быть выбранной, что обеспечивает честные результаты каждый раз."},{"question":"Могу ли я использовать Колесо удачи для розыгрышей?","answer":"Абсолютно! Колесо удачи — это веселый и прозрачный способ выбора победителей розыгрыша. Добавьте имена участников, прокрутите колесо и позвольте всем увидеть результат в реальном времени."},{"question":"Есть ли ограничение на количество вариантов, которые я могу добавить?","answer":"Вы можете добавить столько вариантов, сколько захотите. Однако для наилучшего визуального восприятия мы рекомендуем ограничиться 20 вариантами."},{"question":"Мои варианты сохранены?","answer":"Да, ваши параметры колеса автоматически сохраняются в локальном хранилище вашего браузера. Когда вы вернетесь на страницу, ваши параметры все еще будут там."},{"question":"Является ли Колесо удачи бесплатным для использования?","answer":"Да, колесо удачи абсолютно бесплатно и не требует регистрации. Крутите столько раз, сколько хотите!"}]}}},"tools":{"profilePicture":{"text":"Просматривайте изображения профиля Instagram в полном размере, увеличивайте и загружайте Instagram PP на свое устройство без регистрации."},"story":{"placeHolder":"Имя пользователя или ссылка на историю","downloadButton":"Скачать","recaptcha":"Пожалуйста, завершите проверку человеком.","profile":{"posts":"Сообщения","followers":"Последователи","following":"Следующий"},"properties":["Просматривайте истории Instagram незаметно и сохраняйте конфиденциальность!","Не оставляйте следов, тайно просматривая истории в Instagram.","Защитите свою конфиденциальность. Не нужны ваши учетные данные Instagram, полная безопасность.","Чистый интерфейс и простота использования благодаря простому и минималистичному дизайну.","Все приятные функции бесплатны навсегда.","Не нужно создавать учетную запись","Вы можете сохранить истории, которые не хотите потерять, в течение 24 часов, нажав кнопку загрузки."],"texts":[{"title":"Что такое инструмент Anonymous Instagram Story Viewer?","text":"Это бесплатный инструмент, который позволяет вам просматривать все истории аккаунтов Instagram с общедоступными аккаунтами, не оставляя следов, без какой-либо информации о человеке, которого видели. Вы можете тайно смотреть истории нужного вам человека в Instagram, не будучи замеченным.{br} Если вы хотите посмотреть истории интересующего вас человека, обиженного, с которым вы расстались, человека, которым вы являетесь Собираетесь на интервью, но не можете смотреть, потому что боитесь, что ваше имя увидят, инструмент Simpliers Anonymous Story Viewer для вас."},{"title":"Почему я должен использовать инструмент просмотра Anonymous Instagram Story?","text":"Следить за тем, что происходит в социальных сетях, и при этом защищать свою конфиденциальность — очень распространенная практика в последнее время. Это даже получило название сталкинга. Когда мы преследуем пользователя, мы иногда хотим просмотреть его истории в частном порядке.{br}В этом случае Simpliers предлагает вам инструмент Anonymous Instagram Story Viewer, который является простым в использовании и быстрым инструментом."},{"title":"Как использовать инструмент Anonymous Instagram Story Viewer?","text":"Введите имя человека, чью историю вы хотите посмотреть, и посмотрите его истории. При желании вы можете загружать просматриваемые видео и фотографии.{br}Введите имя учетной записи, чью историю вы хотите посмотреть, и мгновенно просмотрите историю, которой он поделился тайно. Преследуйте профессионально, не оставляя следов. Инструмент Simpliers Instagram Private Story Viewer перечисляет доступные истории учетной записи Instagram, чьи истории вы хотите просмотреть. Вы можете просматривать и загружать истории в полноэкранном режиме, нажимая на эти истории.{br}Анонимное средство просмотра историй Instagram от Simpliers поможет вам без труда смотреть и загружать HD-истории Instagram без следа."}],"topBar":{"subscriptionExists":{"title":"Вы можете смотреть неограниченное количество анонимных историй."},"subscriptionNotExists":{"title":"Подпишитесь, чтобы смотреть неограниченное количество историй.","cta":"Смотри"}}},"exportComments":{"title":"Экспортировать комментарии Instagram"}}}`),e=JSON.pars